{
  "proposed_features": [
    {
      "name": "log1p_x1",
      "op": "log1p",
      "inputs": ["x1"],
      "semantic_rationale": "A scale transformation of a nonnegative measurement; it does not assume an undocumented business meaning.",
      "statistical_rationale": "Compresses large values and represents relative differences. Benefit may be limited for tree models because the transformation is monotonic.",
      "leakage_assessment": "possible",
      "business_interpretation": "Represents proportional rather than absolute differences in x1. Business meaning and pre-prediction availability require confirmation."
    },
    {
      "name": "log1p_x15",
      "op": "log1p",
      "inputs": ["x15"],
      "semantic_rationale": "Preserves zero while compressing the scale of a nonnegative measurement with a wide observed range.",
      "statistical_rationale": "May reduce sensitivity to extreme magnitudes for scale-sensitive models; incremental value for gradient boosting must be validated.",
      "leakage_assessment": "possible",
      "business_interpretation": "Distinguishes relative levels of x15 without claiming that it measures usage, spending, or duration."
    },
    {
      "name": "is_zero_x10",
      "op": "is_zero",
      "inputs": ["x10"],
      "semantic_rationale": "Separates zero from positive values without treating the undocumented integer field as a specific event count.",
      "statistical_rationale": "The median is zero, making a zero-versus-positive threshold a plausible compact representation. Trees may already recover this distinction.",
      "leakage_assessment": "possible",
      "business_interpretation": "Identifies customers whose recorded x10 value is zero; whether zero means absence, inactivity, or a coding convention is unknown."
    },
    {
      "name": "is_zero_x16",
      "op": "is_zero",
      "inputs": ["x16"],
      "semantic_rationale": "Tests whether zero is a distinct state of this nonnegative measurement.",
      "statistical_rationale": "Can expose a boundary effect distinct from variation among positive values. Zero frequency and incremental predictive value require validation.",
      "leakage_assessment": "possible",
      "business_interpretation": "Flags a recorded zero in x16. No specific operational interpretation is justified until its definition is supplied."
    }
  ],
  "candidate_judgements": {
    "cand_seconds_per_call": {
      "decision": "reject",
      "reason": "No columns are documented as seconds or call counts, and the recipe inputs are unspecified. Units, denominator handling, and pre-prediction availability cannot be verified; its AUC does not establish semantic validity."
    },
    "cand_failure_rate": {
      "decision": "reject",
      "reason": "Failures and eligible attempts are not identified. The numerator, denominator, observation window, and availability must be documented before this can be accepted as a rate."
    },
    "cand_key_log": {
      "decision": "reject",
      "reason": "x11 is an excluded identifier or collection artifact. A logarithm preserves its ordering and does not remove the suspected outcome-related assignment signal."
    },
    "cand_post_flag": {
      "decision": "reject",
      "reason": "x7 appears to record a post-churn departure reason and is explicitly excluded. Converting it to an indicator retains likely outcome leakage."
    },
    "cand_friday": {
      "decision": "accept",
      "reason": "This is a transparent encoding of a documented weekday value and requires neither invented domain mappings nor target information. Acceptance is provisional: verify that x14 describes an event known at prediction time, not cancellation or another post-outcome event. Its AUC alone is not justification."
    },
    "cand_target_mean": {
      "decision": "reject",
      "reason": "Computing target means using evaluation rows leaks evaluation labels. Any replacement must use out-of-fold training encodings and mappings fitted exclusively on the corresponding training partition."
    }
  }
}

{
  "proposed_features": [
    {
      "name": "seconds_per_call",
      "op": "ratio",
      "inputs": ["Seconds_of_Use", "Frequency_of_use"],
      "semantic_rationale": "Total call duration divided by call count estimates average call duration during months 1–9, assuming both columns cover the same calls.",
      "statistical_rationale": "Separates call duration from overall activity volume. Return missing when the denominator is zero; validate incremental benefit within training folds.",
      "leakage_assessment": "none",
      "business_interpretation": "Distinguishes customers making many short calls from those making fewer long calls."
    },
    {
      "name": "failures_per_call",
      "op": "ratio",
      "inputs": ["Call_Failure", "Frequency_of_use"],
      "semantic_rationale": "Normalizes call failures by calling activity during the observation window. This is failures per recorded call, not necessarily the probability that an attempted call fails.",
      "statistical_rationale": "May distinguish service-quality burden from exposure volume even though raw failures have weak univariate association. Return missing for zero call count; small denominators can produce unstable ratios.",
      "leakage_assessment": "none",
      "business_interpretation": "Identifies customers experiencing many failures relative to their calling activity."
    },
    {
      "name": "calls_per_contact",
      "op": "ratio",
      "inputs": ["Frequency_of_use", "Distinct_Called_Numbers"],
      "semantic_rationale": "Call count divided by distinct called numbers measures average calling frequency per contacted number.",
      "statistical_rationale": "Separates repeated contact from breadth of calling activity. Return missing when distinct called numbers is zero and investigate inconsistent positive-call, zero-contact records.",
      "leakage_assessment": "none",
      "business_interpretation": "Higher values indicate more repeated calling within the customer's set of contacts."
    },
    {
      "name": "sms_per_call",
      "op": "ratio",
      "inputs": ["Frequency_of_SMS", "Frequency_of_use"],
      "semantic_rationale": "Compares text-message activity with voice-call activity over the same observation window.",
      "statistical_rationale": "Captures communication-channel mix rather than absolute usage. Return missing for zero call count; check sensitivity to small denominators.",
      "leakage_assessment": "none",
      "business_interpretation": "Distinguishes text-oriented from voice-oriented usage patterns."
    },
    {
      "name": "log_seconds_of_use",
      "op": "log1p",
      "inputs": ["Seconds_of_Use"],
      "semantic_rationale": "Expresses nonnegative total call duration on a compressed scale while preserving zero usage.",
      "statistical_rationale": "Compresses the large observed range and may help scale-sensitive models. It preserves ordering, so it adds no new univariate ranking information and may offer little benefit to gradient boosting.",
      "leakage_assessment": "none",
      "business_interpretation": "Represents differences in usage proportionally rather than as absolute seconds."
    },
    {
      "name": "no_voice_usage",
      "op": "is_zero",
      "inputs": ["Seconds_of_Use"],
      "semantic_rationale": "Flags customers with no recorded voice-call duration during months 1–9; it does not imply absence of SMS activity.",
      "statistical_rationale": "Makes a potentially distinct zero-usage state explicit. It is redundant with a suitable tree split, so retain only if validation shows benefit.",
      "leakage_assessment": "none",
      "business_interpretation": "Identifies customers with no observed voice engagement who may warrant a different retention approach."
    }
  ],
  "candidate_judgements": {
    "cand_seconds_per_call": {
      "decision": "accept",
      "reason": "A meaningful pre-outcome usage feature if defined as Seconds_of_Use / Frequency_of_use over the same window. Handle zero denominators as missing. Acceptance is based on semantics and availability, not its development AUC."
    },
    "cand_failure_rate": {
      "decision": "accept",
      "reason": "Failures normalized by calling exposure are meaningful using months 1–9 data. Confirm the recipe and handle zero denominators. If defined as Call_Failure / Frequency_of_use, interpret it as failures per recorded call, not a failure probability unless the denominator is confirmed to count all attempts."
    },
    "cand_key_log": {
      "decision": "reject",
      "reason": "record_key is an extract-assigned identifier and potential leakage artifact. A logarithm does not remove its provenance or suspicious target association."
    },
    "cand_post_flag": {
      "decision": "reject",
      "reason": "deactivation_reason is recorded upon deactivation and is not established as available at the month-9 prediction cutoff. Its indicator inherits outcome-time leakage."
    },
    "cand_friday": {
      "decision": "reject",
      "reason": "Warehouse load weekday is an extraction artifact rather than customer behavior. Its association may reflect processing or sampling patterns that will not generalize."
    },
    "cand_target_mean": {
      "decision": "reject",
      "reason": "Computing target means on the full table exposes evaluation outcomes and leaks target information. A separate implementation would require out-of-fold encoding for training and mappings learned exclusively from training data for validation or inference."
    }
  }
}

